import assert from "node:assert/strict";
import { test } from "node:test";
import { correctedArmorNameIndex } from "../src/overlay/armor-index-corrections.js";

/**
 * These assertions pin real, fingerprint-verified entries from the checked-
 * in `armor-index-corrections.json` (generated by `scripts/generate-armor-
 * corrections.ts` against a real EBOOT — see that file and `emit/armor.ts`'s
 * module doc comment for methodology). Confirmed by hand against real disc
 * bytes: raw `head[12]`'s stats (defense 20, fire -6/water -5/thunder 2/
 * dragon 2, slots 1, price 2300) exactly match committed "Vespoid Helm"
 * (name index 11) — NOT "Vespoid Cap" (name index 12), which raw-position
 * naming would have assumed. Raw `head[11]`'s own stats (defense 18) don't
 * match "Vespoid Cap" (defense 10) either, so its true identity is unknown
 * and it's suppressed rather than guessed.
 */
test("correctedArmorNameIndex remaps a fingerprint-confirmed drifted entry", () => {
  assert.equal(correctedArmorNameIndex("head", 12), 11);
});

test("correctedArmorNameIndex suppresses a raw position whose name was claimed elsewhere", () => {
  assert.equal(correctedArmorNameIndex("head", 11), null);
});

test("correctedArmorNameIndex falls back to raw index when no correction or suppression applies", () => {
  // Index 0 is the "dummy"/placeholder entry in every slot — never touched
  // by fingerprint matching (no committed counterpart to match against).
  assert.equal(correctedArmorNameIndex("head", 0), 0);
});

/**
 * Pins the coverage improvement from excluding `slots` from the required
 * fingerprint (see `scripts/generate-armor-corrections.ts`'s module doc
 * comment). Real bytes: raw `head[19]`'s stats (defense 22, fire 2/water -2/
 * thunder 3/dragon -1, rarity 3, price 2700) exactly match committed
 * "Genprey Helm" on every field *except* `slots` (raw reads 0, committed
 * says 1) — one of many male/female-paired entries where `slots` is
 * transposed between the two variants relative to committed data. The old
 * fingerprint (which required an exact `slots` match) rejected this as "no
 * match" and left `head[19]` on unconfirmed raw-position naming (which
 * would have wrongly resolved to name index 19, not 17); the core
 * fingerprint (defense/resistances/rarity/price only) still uniquely
 * identifies it.
 */
test("correctedArmorNameIndex resolves an entry whose only mismatching field is slots", () => {
  assert.equal(correctedArmorNameIndex("head", 19), 17);
  assert.equal(correctedArmorNameIndex("head", 20), 18);
});
